    expect((await ask(app, "SUP-1", true)).status).toBe(201);
    expect((await ask(app, "SUP-1", true)).status).toBe(201);
    expect(countRequests(db)).toBe(1);
    const row = db.prepare("SELECT pressed FROM suggestion_requests").get() as { pressed: number };
    expect(row.pressed).toBe(1);
  });
