          }
          record(err.status < 500 ? "refused" : "failed", err.code);
          return { isError: true, content: text(errorBody(err).body) };
        } finally {
          running.finish();
        }
      },
    );
  }
  return server;
}

/** The agent behind a verified key, carried from the bearer check to the tools. */
function actorOf(authInfo: AuthInfo | undefined): Actor {
  const actor = authInfo?.extra?.actor as Actor | undefined;
  if (actor === undefined) throw new HttpError(401, "not_signed_in", "Send a connection key.");
  return actor;
}

/**
 * The middleware for POST /mcp, in order: refuse a browser page from another site, read the
 * JSON body, check the connection key with the SDK's bearer check, refuse a body the JSON
 * parser did not read and a batch, end a call the client cancelled, apply the write allowance to tool calls that change
 * something, then hand the request to the SDK's handler.
 */
export function mcpEndpoint(
  service: TicketService,
  connections: ConnectionService,
  writeLimit: RequestHandler,
): RequestHandler[] {
  const verifier = {
    async verifyAccessToken(token: string): Promise<AuthInfo> {
      const actor = connections.authenticate(token);
      if (actor === null || actor.connection === undefined) {
        throw new OAuthError(
          OAuthErrorCode.InvalidToken,
          "That connection key is not valid. Keys are shown once: ask an admin to revoke this connection and issue a new one.",
        );
      }
      return {
        token,
        clientId: String(actor.connection.id),
        scopes: actor.scopes ?? [],
        // The key is checked again on every request, so this short window never outlives a
        // revocation by more than one request.
        expiresAt: Math.floor(Date.now() / 1000) + 60,
        extra: { actor },
      };
    },
  };
  const runningCalls = createRunningCalls();
  const handler = createMcpHandler(({ authInfo }) =>
    buildServer(service, connections, actorOf(authInfo), runningCalls),
  );
  const node = toNodeHandler(handler);
  const writing = new Set(TOOL_ACTIONS.filter((row) => row.method !== "get").map((r) => r.name));

  return [
    // A browser page may only call this from this site. Programs send no Origin at all.
    (req, res, next) => originValidation([req.hostname])(req, res, next),
    express.json({ limit: "100kb" }),
    requireBearerAuth({ verifier }),
    (req, res, next) => {
      // A body the JSON parser above skipped, such as one whose Content-Type it does not
      // take for JSON, would be read by the SDK itself, past the size limit, the batch check
      // and the write allowance. The SDK's test of the type is looser than the parser's.
      if (req.method === "POST" && req.body === undefined) {
        next(
          new HttpError(
            415,
            "bad_request",
            "Send one JSON-RPC message as the body, with Content-Type: application/json.",
          ),
        );
        return;
      }
      // One JSON-RPC message a request. The SDK would run every call in an array, and the
      // write allowance below counts one call a request. The SDK's own client never batches.
      if (Array.isArray(req.body)) {
        res.status(400).json({
          jsonrpc: "2.0",
          error: {
            code: -32600,
            message: "Batches are not accepted. Send one JSON-RPC message in one request.",
          },
          id: null,
        });
        return;
      }
      next();
    },
    (req, _res, next) => {
      // A client that cancels a call sends notifications/cancelled in a request of its own.
      // The SDK still answers it below; this ends the call it names, if that call is running.
      const body = req.body as { method?: unknown; params?: { requestId?: unknown } } | undefined;
      if (body?.method === "notifications/cancelled" && body.params?.requestId !== undefined) {
        const actor = actorOf((req as { auth?: AuthInfo }).auth);
        runningCalls.cancel(String(actor.connection?.id), body.params.requestId);
      }
      next();
    },
    (req, res, next) => {
      const body = req.body as { method?: unknown; params?: { name?: unknown } } | undefined;
      const call = body?.method === "tools/call" ? body.params?.name : undefined;
      if (typeof call === "string" && writing.has(call)) {
        // The same allowance as the JSON API, counted for the same connection.
        req.actor = actorOf((req as { auth?: AuthInfo }).auth);
        writeLimit(req, res, next);
        return;
      }
      next();
    },
    (req, res) => void node(req, res, req.body),
  ];
}

/**
 * Answers an error raised on /mcp before the SDK answers (a body that is not JSON, is too
 * large or was not read, or the write allowance) as a JSON-RPC error an MCP client can read,
 * never as a page. The HTTP status stays, and `data` carries the same code, hint and retry
 * flag as the API.
 */
export const mcpErrorHandler: ErrorRequestHandler = (err, _req, res, next) => {
  if (res.headersSent) {
    next(err);
    return;
  }
  const { status, body } = errorBody(err);
  res.status(status).json({
    jsonrpc: "2.0",
    error: { code: -32000, message: body.error.message, data: body.error },
    id: null,
  });
};

import type { ErrorRequestHandler, RequestHandler } from "express";
import { rememberProblem } from "./pages/saved.js";

/** An error that carries an HTTP status and a stable machine-readable code. */
export class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

/**
 * A 400 for input that breaks the rules. Besides the one-line message it carries the
 * messages per field, for example { title: ["..."] }, so a form can show each one in place.
 */
export class ValidationError extends HttpError {
  constructor(
    message: string,
    readonly fieldErrors: Record<string, string[] | undefined>,
  ) {
    super(400, "validation_error", message);
    this.name = "ValidationError";
  }
}

/** What the demo's read-only admin preview is told when it tries to change something. */
export const READ_ONLY_REFUSAL =
  "The admin preview is read-only. Use the menu at the top right to act as the customer or the team.";

/**
 * The 403 for an action this person may not do. The demo's read-only admin preview is told
 * why, and how to try the action, instead of a bare refusal.
 */
export function forbidden(actor: { readOnly?: boolean }): HttpError {
  const message = actor.readOnly === true ? READ_ONLY_REFUSAL : "You are not allowed to do that.";
  return new HttpError(403, "forbidden", message);
}

/** The demo was not seeded with its assistant sample, so assistant connections are off. */
export function demoNotReady(): HttpError {
  return new HttpError(
    503,
    "demo_not_ready",
    "Assistant connections are off on this demo until its operator resets its database.",
  );
}

type ShownError = {
  status: number;
  code: string;
  message: string;
  fields?: Record<string, string[]>;
};

// What to do next, for each error code a caller can meet. A code not listed falls back to a
// hint for its status.
export const HINTS: Record<string, string> = {
  validation_error: "Fix the fields named in `fields` and send again.",
  invalid_key: "Ticket keys look like SUP-42. Check the key and send again.",
  not_signed_in: "Sign in first. A program sends a connection key: Authorization: Bearer <key>.",
  invalid_connection_key:
    "The key is wrong, revoked or expired. Keys are shown once: ask an admin to revoke this connection and issue a new one.",
  cross_site_request:
    "Send the request from a page on this site. A program signs in with a connection key instead.",
  forbidden: "Your role may not do this. GET /api lists who may call each action.",
  not_found: "Check the address. GET /api is a guide to every action.",
  ticket_not_found: "Check the key. GET /api/tickets lists the tickets you may see.",
  ticket_deleted: "This ticket was deleted permanently. Its number is never used again.",
  ticket_archived: "Restore the ticket first, if your role may (POST .../restore).",
  needs_owner: "Take the ticket first (POST .../take), then change the status.",
  keeps_owner:
    "Work has started, so the ticket keeps an owner. Hand it to a team member instead (POST .../hand-off).",
  needs_customer:
    "A status change does not resolve a ticket. The customer confirms a fix with Yes, which its owner asks with Ask the customer to verify (POST /api/tickets/{key}/ready); its owner or an admin can also resolve it with a reason (POST /api/tickets/{key}/resolve), and a team member can resolve one nobody owns yet, becoming its owner.",
  not_in_progress: "Move the ticket to in_progress first.",
  not_waiting: "The team has not asked this question yet, or it was withdrawn.",
  only_filer_reopens:
    "A resolved ticket moves only by reopening it (POST .../reopen): the customer who filed it can, and so can its owner or an admin when the team resolved it.",
  customer_confirmed:
    "The customer confirmed this fix with their Yes, so only they can reopen it. Reply on the ticket if it needs more work.",
  not_owner: "Only the ticket's owner can do this. Ask them, or have it handed to you.",
  no_owner:
    "Nobody owns this ticket, so there is nothing to release. Take it (POST .../take) to work on it.",
  already_owned: "Someone already owns this ticket. Ask them to hand it to you.",
  not_new: "This ticket has already started.",
  not_resolved: "The ticket is still open; there is nothing to reopen.",
  owner_changed: "Reload the ticket: it has changed hands since you opened it.",
  ticket_changed:
    "Get the ticket again and look at what changed. Then send again with its current version as expected_version, or leave expected_version out to skip the check.",
  not_open:
    "The ticket is resolved. The customer who filed it can reopen it, and so can its owner or an admin when the team resolved it.",
  question_open: "Withdraw the open question first (POST .../withdraw-question), then ask again.",
  no_interpretation: "The team has not offered any wording for the check.",
  suggestions_full:
    "Other assistants already offer enough ways to verify this ticket. Offer fewer, or none.",
  suggestion_gone: "Get the ticket again and pick one of its offered check_suggestions.",
  check_exists: "The ticket already has a check. Edit the ticket to change it.",
  no_assistant_listening:
    "Write the check yourself, or ask again once the team's assistant is running.",
  request_not_found: "Answer only the requests wait_for_requests handed you.",
  request_closed: "Nothing to do for this request. Call wait_for_requests for the next one.",
  question_changed: "Get the ticket again and answer with its current ready_token.",
  idempotency_key_reused:
    "Use a new idempotency key for a new request. Reuse a key only to retry the very same request.",
  budget_full: "The demo has no room for more of these. Nothing to retry.",
  demo_not_ready:
    "The demo's operator must reset its database (docs/DEPLOY.md, Resetting the demo). Sending it again will not help.",
  too_many_requests: "Wait for the time in the Retry-After header, then send again.",
  bad_request: "The request could not be read. Send JSON with Content-Type: application/json.",
  internal_error: "Something failed on the server. Try again later.",
};

/** Refusals that sending the same request again can never change, whatever their status. */
const NEVER_RETRY = new Set(["demo_not_ready"]);

/** Whether sending the same request again can work: only after waiting, or after a failure. */
function canRetry(shown: ShownError): boolean {
  if (NEVER_RETRY.has(shown.code)) return false;
  return shown.status === 429 || shown.status >= 500;
}

/** The JSON body of an error: what happened, what to do next, and whether to retry. */
export function errorBody(err: unknown) {
  const shown = describeError(err);
  return {
    status: shown.status,
    body: {
      error: {
        code: shown.code,
        message: shown.message,
        hint:
          HINTS[shown.code] ?? (shown.status >= 500 ? HINTS.internal_error! : HINTS.bad_request!),
        retry: canRetry(shown),
        ...(shown.fields ? { fields: shown.fields } : {}),
      },
    },
  };
}

/**
 * Decides what to tell the caller about anything that was thrown. An unexpected error is
 * logged here and its details are never sent out.
 */
function describeError(err: unknown): ShownError {
  if (err instanceof ValidationError) {
    const fields: Record<string, string[]> = {};
    for (const [name, messages] of Object.entries(err.fieldErrors)) {
      if (messages !== undefined) fields[name] = messages;
    }
    return { status: err.status, code: err.code, message: err.message, fields };
  }
  if (err instanceof HttpError) {
    return { status: err.status, code: err.code, message: err.message };
  }
  const status = httpStatusOf(err);
  if (status !== undefined && status >= 400 && status < 500) {
    return { status, code: "bad_request", message: "The request was invalid." };
  }
  console.error(err);
  return { status: 500, code: "internal_error", message: "Internal server error." };
}

/**
 * The HTTP status a library put on an error, if any. Express's body parser puts a number in
 * "status". The sign-in library puts a word there ("BAD_REQUEST") and the number in
 * "statusCode".
 */
function httpStatusOf(err: unknown): number | undefined {
  if (typeof err !== "object" || err === null) return undefined;
  const { status, statusCode } = err as { status?: unknown; statusCode?: unknown };
  if (typeof status === "number") return status;
  if (typeof statusCode === "number") return statusCode;
  return undefined;
}

// The JSON API answers errors as JSON.

export const notFoundHandler: RequestHandler = (req, _res, next) => {
  next(new HttpError(404, "not_found", `No route for ${req.method} ${req.baseUrl}${req.path}`));
};

export const errorHandler: ErrorRequestHandler = (err, _req, res, next) => {
  if (res.headersSent) {
    next(err);
    return;
  }
  const { status, body } = errorBody(err);
  if (status === 401) {
    // A 401 names the scheme that works here (RFC 9110), and says when a key was sent but
    // is not valid (RFC 6750). Pages do not get this: they send the browser to sign-in.
    const wrongKey = body.error.code === "invalid_connection_key";
    res.set("WWW-Authenticate", wrongKey ? 'Bearer error="invalid_token"' : "Bearer");
  }
  res.status(status).json(body);
};

// Pages answer the same errors as a readable HTML page.

export const pageNotFoundHandler: RequestHandler = (_req, _res, next) => {
  next(new HttpError(404, "not_found", "There is no page at this address."));
};

/**
 * A refusal as the ticket page shows it. The page that comes back is the ticket as it is now, so
 * a refusal for an old version says so. The API's message stops before that sentence.
 */
export function onTicketPage(err: { code: string; message: string }): string {
  if (err.code === "ticket_changed") return `${err.message} This is the ticket as it is now.`;
  return err.message;
}

export const pageErrorHandler: ErrorRequestHandler = (err, req, res, next) => {
  if (res.headersSent) {
    next(err);
    return;
  }
  const shown = describeError(err);
  if (shown.status === 401) {
    // Nobody is signed in: send the browser to the sign-in page instead of an error. For
    // a page that was being opened, remember its address so sign-in can return to it.
    const next = req.method === "GET" ? `?next=${encodeURIComponent(req.originalUrl)}` : "";
    res.redirect(303, `/sign-in${next}`);
    return;
  }
  // A refused action on a ticket goes back to that ticket, with the reason shown there.
  const ticketAction = /^\/tickets\/([A-Z]{2,6}-[1-9][0-9]*)\/[a-z/-]+$/.exec(req.path);
  if (
    req.method === "POST" &&
    ticketAction !== null &&
    (shown.status === 403 || shown.status === 409) &&
    // A forged request from another site gets a plain refusal, never a trip to the ticket.
    shown.code !== "cross_site_request"
  ) {
    rememberProblem(res, onTicketPage(shown));
    res.redirect(303, `/tickets/${ticketAction[1]}`);
    return;
  }
  let title = "Something went wrong";
  if (shown.status === 404) title = "Not found";
  else if (shown.status < 500) title = "That request did not work";
  res.status(shown.status).render("error", { title, message: shown.message, status: shown.status });
};

import type { Actor } from "../actor.js";
import { HttpError, ValidationError } from "../errors.js";
import { parse } from "../validation.js";
import { requireNotArchived, requirePermission, requireVersion, saved } from "./checks.js";
import { noQuestion } from "./history.js";
import * as repository from "./repository.js";
import { changeStatusSchema, handOffSchema, versionOnlySchema } from "./schemas.js";
import type { Shared } from "./shared.js";
import type { Ticket } from "./types.js";

// The status workflow and who owns a ticket: take it, start work, release it, send it back to
// New, and hand it to another team member. Resolving and reopening are in resolve-and-reopen.ts.

/** The answer to anyone who tries to resolve a ticket by changing its status. */
function needsCustomer(key: string): HttpError {
  return new HttpError(
    409,
    "needs_customer",
    `A status change does not resolve ticket ${key}. The customer confirms a fix by answering "Did this fix it?", which its owner asks with "Ask the customer to verify"; the team can also resolve it with a reason.`,
  );
}

/** Only the ticket's own owner starts work on it, and only once it has one. */
function requireOwnerStarts(key: string, row: repository.TicketRow, actor: Actor): void {
  if (row.owner_id === null) {
    throw new HttpError(409, "needs_owner", `Take ticket ${key} before moving it to In Progress.`);
  }
  if (row.owner_id !== actor.id) {
    throw new HttpError(
      403,
      "not_owner",
      `Only ${row.owner_name ?? "its owner"}, who owns ticket ${key}, starts work on it.`,
    );
  }
}

/** Only the ticket's owner, or an admin, sends a ticket back to New. */
function requireOwnerOrAdminReturns(key: string, row: repository.TicketRow, actor: Actor): void {
  if (row.owner_id === actor.id || actor.role === "admin") return;
  throw new HttpError(
    403,
    "not_owner",
    `Only ${row.owner_name ?? "its owner"}, who owns ticket ${key}, or an admin can return it to New.`,
  );
}

export function createWorkflow(shared: Shared, teamMembers: () => { id: string; name: string }[]) {
  const { db, requireRow, log, setOwner, endAgent, withdrawQuestion, toTicket } = shared;

  /**
   * Sends an in-progress ticket back to New, with no owner, so anyone on the team can take it.
   * An open question to the customer is withdrawn first, with its own history entry, and any
   * assistant's work on the ticket ends, as on a hand-off. Call it inside a transaction.
   */
  function returnToNew(
    key: string,
    before: repository.TicketRow,
    actor: Actor,
  ): repository.TicketRow {
    requireOwnerOrAdminReturns(key, before, actor);
    const now = new Date().toISOString();
    if (before.ready_at !== null) {
      repository.clearReady(db, before.id, now);
      log(before.id, actor, "question_withdrawn", {}, now);
    }
    endAgent(before, "the ticket went back to New", actor, now);
    // The status first: the database refuses an in-progress ticket without an owner.
    repository.updateTicketStatus(db, before.id, "new", now);
    const unowned = setOwner(before, null, null, actor);
    log(before.id, actor, "status_changed", { from: before.status, to: "new" }, now);
    return { ...unowned, status: "new", ...noQuestion, updated_at: now };
  }

  return {
    /**
     * Checks the input, then saves the new status and its event together. It starts work or
     * sends the ticket back to New; it never resolves one.
     */
    changeStatus(key: string, input: unknown, actor: Actor): Ticket {
      const row = db.transaction(() => {
        const before = requireRow(key, actor);
        // An agent asking to resolve gets the real reason first, whatever its scopes: nobody
        // resolves a ticket by changing its status.
        const asked = changeStatusSchema.safeParse(input);
        if (
          actor.kind === "agent" &&
          asked.success &&
          asked.data.status === "resolved" &&
          before.status !== "resolved"
        ) {
          throw needsCustomer(key);
        }
        requirePermission(actor, "change_status", before);
        const { status, expected_version } = parse(changeStatusSchema, input);
        requireNotArchived(key, before);
        if (before.status === status) {
          // Work that has started is the owner's: anyone else asking to start it is refused,
          // even though nothing would change. Asking for New on a New ticket changes nothing.
          if (status === "in_progress") requireOwnerStarts(key, before, actor);
          return before; // nothing changes, so nothing is logged
        }
        if (status === "resolved") throw needsCustomer(key);
        // The status moves only by the workflow's own steps: start work, or send it back to New.
        if (before.status === "resolved") {
          throw new HttpError(
            409,
            "only_filer_reopens",
            `Ticket ${key} is resolved. A resolved ticket moves only by reopening it.`,
          );
        }
        if (status === "new") {
          // Checked here so the owner rule answers before the version check.
          // returnToNew checks it again for its other callers.
          requireOwnerOrAdminReturns(key, before, actor);
          requireVersion(key, before, expected_version);
          return returnToNew(key, before, actor);
        }
        requireOwnerStarts(key, before, actor);
        requireVersion(key, before, expected_version);
        const now = new Date().toISOString();
        repository.updateTicketStatus(db, before.id, status, now);
        log(before.id, actor, "status_changed", { from: before.status, to: status }, now);
        return { ...before, status, ready_at: null, ready_token: null, updated_at: now };
      })();
      return toTicket(saved(db, row), actor);
    },

    /**
     * Makes the actor the owner of an unowned ticket. A ticket someone else owns is refused:
     * giving it to someone else is a hand-off.
     */
    takeTicket(key: string, actor: Actor, input: unknown = {}): Ticket {
      const row = db.transaction(() => {
        const before = requireRow(key, actor);
        requirePermission(actor, "take", before);
        const { expected_version } = parse(versionOnlySchema, input ?? {});
        requireNotArchived(key, before);
        if (before.owner_id === actor.id) return before; // already theirs
        // Take is for the inbox. Someone else's ticket is handed over, not taken.
        if (before.owner_id !== null) {
          throw new HttpError(
            409,
            "already_owned",
            `${before.owner_name ?? "Someone"} already owns ticket ${key}.`,
          );
        }
        if (before.status === "resolved") {
          throw new HttpError(409, "not_open", `Ticket ${key} is resolved.`);
        }
        requireVersion(key, before, expected_version);
        return setOwner(before, actor.id, actor.name, actor);
      })();
      return toTicket(saved(db, row), actor);
    },

    /**
     * Takes an unowned ticket and starts work on it, in one step. A ticket someone else owns
     * is refused: taking it from them is a hand-off.
     */
    takeAndStart(key: string, actor: Actor, input: unknown = {}): Ticket {
      const row = db.transaction(() => {
        let before = requireRow(key, actor);
        requirePermission(actor, "take", before);
        requirePermission(actor, "change_status", before);
        const { expected_version } = parse(versionOnlySchema, input ?? {});
        requireNotArchived(key, before);
        if (before.status !== "new") {
          throw new HttpError(
            409,
            "not_new",
            `Ticket ${key} is not new, so there is nothing to start.`,
          );
        }
        if (before.owner_id !== null && before.owner_id !== actor.id) {
          throw new HttpError(
            409,
            "already_owned",
            `${before.owner_name ?? "Someone"} already owns ticket ${key}.`,
          );
        }
        requireVersion(key, before, expected_version);
        if (before.owner_id === null) before = setOwner(before, actor.id, actor.name, actor);
        const now = new Date().toISOString();
        repository.updateTicketStatus(db, before.id, "in_progress", now);
        log(before.id, actor, "status_changed", { from: "new", to: "in_progress" }, now);
        return { ...before, status: "in_progress" as const, updated_at: now };
      })();
      return toTicket(saved(db, row), actor);
    },

    /** Leaves the ticket without an owner. Only its owner, and not while it is in progress. */
    releaseTicket(key: string, actor: Actor, input: unknown = {}): Ticket {
      const row = db.transaction(() => {
        const before = requireRow(key, actor);
        requirePermission(actor, "release", before);
        const { expected_version } = parse(versionOnlySchema, input ?? {});
        requireNotArchived(key, before);
        if (before.owner_id === null) {
          throw new HttpError(
            409,
            "no_owner",
            `Nobody owns ticket ${key}, so there is nothing to release.`,
          );
        }
        // Only the owner lets go of a ticket, and only before work starts.
        if (before.owner_id !== actor.id) {
          throw new HttpError(
            403,
            "not_owner",
            `Only ${before.owner_name ?? "its owner"}, who owns ticket ${key}, can release it.`,
          );
        }
        if (before.status === "resolved") {
          throw new HttpError(409, "not_open", `Ticket ${key} is resolved.`);
        }
        if (before.status === "in_progress") {
          throw new HttpError(
            409,
            "keeps_owner",
            `Ticket ${key} is in progress, so it must keep an owner. Someone else can take it.`,
          );
        }
        requireVersion(key, before, expected_version);
        return setOwner(before, null, null, actor);
      })();
      return toTicket(saved(db, row), actor);
    },

    /**
     * The owner, or an admin, hands the ticket straight to another team member. The form says
     * whom it expects to own the ticket now, so a hand-off made from an old page is refused. An
     * open question to the customer is withdrawn: the new owner asks again.
     */
    handOff(key: string, input: unknown, actor: Actor): Ticket {
      const row = db.transaction(() => {
        const before = requireRow(key, actor);
        requirePermission(actor, "hand_off", before);
        const { to, expected_owner, expected_version } = parse(handOffSchema, input);
        requireNotArchived(key, before);
        if (before.status === "resolved") {
          throw new HttpError(409, "not_open", `Ticket ${key} is resolved.`);
        }
        if (before.owner_id !== actor.id && actor.role !== "admin") {
          throw new HttpError(
            403,
            "not_owner",
            `Only ${before.owner_name ?? "its owner"}, who owns ticket ${key}, or an admin can hand it off.`,
          );
        }
        if ((before.owner_id ?? "") !== expected_owner) {
          throw new HttpError(
            409,
            "owner_changed",
            `Ticket ${key} has changed hands since you opened it. Reload it and try again.`,
          );
        }
        const target = teamMembers().find((member) => member.id === to);
        if (target === undefined) {
          throw new ValidationError("Choose a team member.", { to: ["Choose a team member."] });
        }
        if (target.id === before.owner_id) return before;
        requireVersion(key, before, expected_version);
        withdrawQuestion(before);
        // A new owner chooses their own help: the old owner's agent hand-off ends.
        endAgent(before, "the ticket changed hands", actor, new Date().toISOString());
        return {
          ...setOwner(before, target.id, target.name, actor),
          ready_at: null,
          ready_token: null,
        };
      })();
      return toTicket(saved(db, row), actor);
    },

    /** The team members this ticket could be handed to: everyone eligible but its owner. */
    handOffCandidates(ticket: Ticket): { id: string; name: string }[] {
      return teamMembers().filter((member) => member.id !== ticket.owner_id);
    },
  };
}

